--[[
    Monody Premium - Embedded Artwork Provider
    Provides guaranteed, instant offline photo caching and asset resolution.
]]
local EmbeddedAssets = {}

local function decode64(data)
    local codec = (crypt and crypt.base64 and crypt.base64.decode) or (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode)
    if type(codec) == "function" then
        local ok, result = pcall(codec, data)
        if ok and type(result) == "string" then return result end
    end
    local alphabet, lookup, chunks = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", {}, {}
    for i = 1, 64 do lookup[string.byte(alphabet, i)] = i - 1 end
    for offset = 1, #data, 16384 do
        local part = {}
        for i = offset, math.min(offset + 16383, #data), 4 do
            local a,b,c,d = string.byte(data, i, i+3)
            local value = (lookup[a] or 0)*262144 + (lookup[b] or 0)*4096 + (lookup[c] or 0)*64 + (lookup[d] or 0)
            local one = math.floor(value/65536) % 256
            local two = math.floor(value/256) % 256
            local three = value % 256
            part[#part+1] = d == 61 and (c == 61 and string.char(one) or string.char(one,two)) or string.char(one,two,three)
        end
        chunks[#chunks+1] = table.concat(part)
    end
    return table.concat(chunks)
end

local portraitData = [=[]=]
local cachedUri = nil

function EmbeddedAssets.GetPortraitUri()
    if cachedUri then return cachedUri end
    local customAsset = getcustomasset or getsynasset
    local fn = "monody_anime_portrait.jpg"
    local cPath = "Monody/cache/" .. fn
    local isfileFn = isfile or (getgenv and getgenv().isfile)
    local writefileFn = writefile or (getgenv and getgenv().writefile)
    local makefolderFn = makefolder or (getgenv and getgenv().makefolder)
    
    if type(customAsset) == "function" and type(writefileFn) == "function" then
        pcall(function()
            if makefolderFn then
                pcall(makefolderFn, "Monody")
                pcall(makefolderFn, "Monody/cache")
            end
            local exists = false
            if isfileFn then
                local okCheck, res = pcall(isfileFn, cPath)
                exists = okCheck and res
            end
            if not exists then
                local rawBytes = decode64(portraitData)
                pcall(writefileFn, cPath, rawBytes)
                pcall(writefileFn, fn, rawBytes)
            end
            local okA, uri = pcall(customAsset, cPath)
            if okA and type(uri) == "string" and #uri > 0 then
                cachedUri = uri
            else
                local okA2, uri2 = pcall(customAsset, fn)
                if okA2 and type(uri2) == "string" and #uri2 > 0 then
                    cachedUri = uri2
                end
            end
        end)
    end
    return cachedUri or "rbxassetid://88742259971314"
end

function EmbeddedAssets.BindPortrait(imageLabel)
    if not imageLabel then return end
    task.spawn(function()
        local uri = EmbeddedAssets.GetPortraitUri()
        if uri and imageLabel and imageLabel.Parent then
            imageLabel.Image = uri
        end
    end)
end

return EmbeddedAssets
